// Retrieve the stringified thresholds from metadata
var thresholdsStr = metadata.shared_alarm_thresholds || metadata.alarm_thresholds;

if (thresholdsStr) {
    try {
        var thresholds = JSON.parse(thresholdsStr);

        // Unpack each property directly into metadata
        for (var key in thresholds) {
            if (thresholds.hasOwnProperty(key)) {
                metadata[key] = thresholds[key];
            }
        }
    } catch (e) {
        // Keeps the rule chain running if JSON parsing fails
    }
}

// Delete the unneeded raw string key
delete metadata.shared_alarm_thresholds;
delete metadata.alarm_thresholds;

return {msg: msg, metadata: metadata, msgType: msgType};

