configuration.jsScript:
var events = [];

function evalMetric(val, hiCrit, loCrit, hiWarn, loWarn, hist, name) {
    if (isNaN(val)) return;

    // Create an isolated copy of metadata for this specific alarm event
    var meta = Object.assign({}, metadata);
    meta.alarmType = name + " Alarm";

    // 1. Critical Alarm Check
    if ((hiCrit && val >= hiCrit) || (loCrit && val <= loCrit)) {
        meta.alarmSeverity = "CRITICAL";
        meta.action = "TriggerAlarm";
        events.push({msg: msg, metadata: meta, msgType: msgType});

    // 2. Warning Alarm Check
    } else if ((hiWarn && val >= hiWarn) || (loWarn && val <= loWarn)) {
        meta.alarmSeverity = "WARNING";
        meta.action = "TriggerAlarm";
        events.push({msg: msg, metadata: meta, msgType: msgType});

    // 3. Clear Alarm Check (handles missing hiWarn or loWarn thresholds)
    } else {
        var hiClear = !hiWarn || (val < (hiWarn - hist));
        var loClear = !loWarn || (val > (loWarn + hist));

        if (hiClear && loClear) {
            meta.action = "ClearAlarm";
            events.push({msg: msg, metadata: meta, msgType: msgType});
        }
    }
}

// 1. Humidity Check
evalMetric(
    parseFloat(metadata.rh), 
    parseFloat(metadata.rhHighCritical), parseFloat(metadata.rhLowCritical), 
    parseFloat(metadata.rhHighWarning), parseFloat(metadata.rhLowWarning), 
    parseFloat(metadata.rhHist || 0), "RH"
);

// 2. Temperature Check
evalMetric(
    parseFloat(metadata.temp), 
    parseFloat(metadata.tempHighCritical), parseFloat(metadata.tempLowCritical), 
    parseFloat(metadata.tempHighWarning), parseFloat(metadata.tempLowWarning), 
    parseFloat(metadata.tempHist || 0), "Temperature"
);

// 3. Battery Check
evalMetric(
    parseFloat(metadata.battery), 
    null, parseFloat(metadata.batteryLowCritical), 
    null, parseFloat(metadata.batteryLowWarning), 
    parseFloat(metadata.battHist || 0), "Battery"
);

return events;
